  upgradeSubscription(userId: string, tier: SubscriptionTier): Promise<void>;
}

class PremiumPaymentProcessor implements PaymentProcessor {
  // Implementation of payment processing logic
}

async function processPremiumPayment(
  userId: string,
  payment: PaymentDetails,
  tier: SubscriptionTier,
  processor: PaymentProcessor = new PremiumPaymentProcessor()
): Promise<boolean> {
  if (!processor.validate(payment)) {
    throw new Error('Invalid payment details');
  }
  const amount = processor.calculatePrice(tier);
  if (payment.amount < amount) {
    throw new Error('Insufficient payment amount');
  }
  const paymentSuccessful = await processor.charge(payment, amount);
  if (!paymentSuccessful) {
    return false;
  }
  await processor.upgradeSubscription(userId, tier);
  return true;
}

